import{_ as t,o as i,c as o,a3 as a}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"前端 Chunk 体积与装载边界收口计划","description":"","frontmatter":{},"headers":[],"relativePath":"Plan/frontend-chunk-size-investigation.md","filePath":"Plan/frontend-chunk-size-investigation.md","lastUpdated":1785283012000}'),l={name:"Plan/frontend-chunk-size-investigation.md"};function r(d,e,n,c,s,h){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="前端-chunk-体积与装载边界收口计划" tabindex="-1">前端 Chunk 体积与装载边界收口计划 <a class="header-anchor" href="#前端-chunk-体积与装载边界收口计划" aria-label="Permalink to &quot;前端 Chunk 体积与装载边界收口计划&quot;">​</a></h1><blockquote><p>状态：Monaco ESM-only 与 Tokenizer 资产化已完成；自动分包基线、运行态观测和少量构建边界待按数据推进</p><p>最后更新：2026-07-28</p><p>关联配置：<a href="../../vite.config.ts"><code>vite.config.ts</code></a></p></blockquote><h2 id="_1-当前结论" tabindex="-1">1. 当前结论 <a class="header-anchor" href="#_1-当前结论" aria-label="Permalink to &quot;1. 当前结论&quot;">​</a></h2><p>构建警告不能通过继续提高 <code>chunkSizeWarningLimit</code> 解决，但大 chunk 也不等于首屏瓶颈。当前应分别看安装体积、首页静态闭包、按需工具成本和真实 Tauri 的读取/解析/执行时间。</p><p>已完成的两项高收益治理：</p><ol><li>移除 AMD Monaco，只保留统一 ESM 入口和 Worker 工厂。</li><li>将七个内置 Tokenizer 从 JavaScript 模块拆为构建期 gzip 资产，首次使用时按需解压。</li></ol><p>当前 registry 与插件初始化的实测中位数约 294 ms，没有证据支持全仓改造成异步 catalog。后续只做可回滚的自动分包实验、精确观测和低风险懒加载。</p><h2 id="_2-已完成结果" tabindex="-1">2. 已完成结果 <a class="header-anchor" href="#_2-已完成结果" aria-label="Permalink to &quot;2. 已完成结果&quot;">​</a></h2><h3 id="_2-1-monaco-esm-only" tabindex="-1">2.1 Monaco ESM-only <a class="header-anchor" href="#_2-1-monaco-esm-only" aria-label="Permalink to &quot;2.1 Monaco ESM-only&quot;">​</a></h3><ul><li><code>src/utils/monaco.ts</code> 统一注册 Editor、JSON、CSS、HTML 和 TypeScript Worker。</li><li><code>@guolao/vue-monaco-editor</code> 显式使用本地 ESM Monaco，阻断 CDN fallback。</li><li>移除 <code>@tomjs/vite-plugin-monaco-editor</code>、AMD HTML 注入和完整 <code>min/vs</code> 复制目录。</li><li>Text Diff、Web Canvas、Agent Manager、Quick Action 等运行时入口统一使用同一模块。</li><li>真实 Tauri 窄 E2E 覆盖 Diff Editor、Worker factory 和 AMD/CDN 请求边界。</li></ul><p>2026-07-26 构建记录：</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">实施前</th><th style="text-align:right;">实施后</th></tr></thead><tbody><tr><td><code>dist</code> 原始体积</td><td style="text-align:right;">约 134 MiB</td><td style="text-align:right;">119.35 MiB</td></tr><tr><td>JavaScript 原始体积</td><td style="text-align:right;">91.68 MiB</td><td style="text-align:right;">77.32 MiB</td></tr><tr><td>JavaScript gzip</td><td style="text-align:right;">30.42 MiB</td><td style="text-align:right;">26.86 MiB</td></tr><tr><td>AMD Monaco 复制目录</td><td style="text-align:right;">14.97 MiB</td><td style="text-align:right;">不再生成</td></tr><tr><td>首页额外 AMD Monaco JS</td><td style="text-align:right;">3.64 MiB</td><td style="text-align:right;">0</td></tr></tbody></table><p>Monaco ESM 核心和 Worker 仍是编辑器路由的按需成本，不进入首页 preload，不应为消除单 chunk 警告再次复制或拆出 AMD 运行时。</p><h3 id="_2-2-tokenizer-资产化" tabindex="-1">2.2 Tokenizer 资产化 <a class="header-anchor" href="#_2-2-tokenizer-资产化" aria-label="Permalink to &quot;2.2 Tokenizer 资产化&quot;">​</a></h3><ul><li><code>builtin-tokenizer-assets-manifest.ts</code> 维护七个内置包与 profile 的资产来源。</li><li>Vite 插件在构建期输出 <code>dist/tokenizers/&lt;profile&gt;/*.json.gz</code>，开发模式使用同一路径中间件。</li><li><code>tokenizerAssetService</code> 通过 <code>fflate</code> 解压，并复用现有 Worker 的 <code>needProfileData</code> / <code>profileData</code> 协议。</li><li>Worker 与主线程不再动态导入七个 <code>@lenml/tokenizer-*</code> 大型 JavaScript 入口。</li><li>用户导入和远端缓存 profile 的注册表协议保持不变。</li></ul><p>2026-07-26 构建记录：七个 gzip 资产约 15.54 MiB；JavaScript 降至约 40.87 MiB（gzip 12.05 MiB），相对 Monaco 阶段后的基线减少约 36.45 MiB 原始 JS。14 个资产解压后均与来源字节一致。</p><h2 id="_3-仍需实施" tabindex="-1">3. 仍需实施 <a class="header-anchor" href="#_3-仍需实施" aria-label="Permalink to &quot;3. 仍需实施&quot;">​</a></h2><h3 id="p1-验证自动分包" tabindex="-1">P1：验证自动分包 <a class="header-anchor" href="#p1-验证自动分包" aria-label="Permalink to &quot;P1：验证自动分包&quot;">​</a></h3><p>先移除粗粒度 <code>manualChunks</code> 做可回滚对照，不以“chunk 数更少”作为目标。</p><p>验收必须同时记录：</p><ul><li><code>index.html</code> 静态 preload 数量和原始/gzip 体积；</li><li>Home、普通工具、编辑器、PDF Viewer 和插件路由的按需请求；</li><li><code>dist</code> 总体积与重复依赖；</li><li>真实 Tauri 冷/暖启动各至少 10 次的中位数和 P95；</li><li><code>bun run build:tsc</code> 与 <code>bun run build:vite</code>。</li></ul><p>只有自动分包造成稳定回归时，才增加窄而可解释的分组；禁止为消警告继续提高阈值。</p><h3 id="p3-观测与低风险入口清理" tabindex="-1">P3：观测与低风险入口清理 <a class="header-anchor" href="#p3-观测与低风险入口清理" aria-label="Permalink to &quot;P3：观测与低风险入口清理&quot;">​</a></h3><p>2026-07-27 的三次启动中，44 个 registry、38 个工具和 2 个插件的 <code>registry + plugins</code> 为 200–343 ms，中位数 294 ms；<code>WebView Started -&gt; MainLayout ready</code> 中位数 789 ms。现有证据不支持大规模 <code>ToolDescriptor</code>、异步 discovery 或首次调用实例化。</p><p>先增加统一 performance marks：</p><ul><li><code>bootstrap-start</code>、<code>vue-mounted</code>、<code>window-shown</code>；</li><li><code>app-init-start</code>、<code>registry-imports-done</code>、<code>plugins-loaded</code>；</li><li><code>main-layout-ready</code>、<code>first-route-rendered</code>。</li></ul><p>低风险候选仅限公开方法本来就是异步、且没有启动恢复职责的 registry 壳层，例如 <code>git-committer</code>、<code>window-automator</code>、<code>recall</code>、<code>ffmpeg-tools</code>、<code>git-analyzer</code>、<code>aio-file-operator</code> 和 <code>dir-search</code>。每项必须单独核对直接调用、factory、dispose、插件和类型契约。</p><p>重新评估全局 registry 拆分的触发条件：</p><ul><li><code>registry + plugins</code> 中位数稳定超过 500 ms 或 P95 超过 1 s；</li><li><code>window-shown -&gt; first-route-rendered</code> P95 超过 1 s，且主要成本确认在 registry；</li><li>插件数量增长导致启动耗时近似线性恶化；</li><li>未使用工具产生可观常驻内存、监听器或后台任务；</li><li>Detached / Canvas 因无关主应用依赖出现明确卡顿。</li></ul><h3 id="p4-剩余构建边界" tabindex="-1">P4：剩余构建边界 <a class="header-anchor" href="#p4-剩余构建边界" aria-label="Permalink to &quot;P4：剩余构建边界&quot;">​</a></h3><p>按影响处理，不将所有 warning 都升级为阻塞项：</p><ul><li>ineffective dynamic import；</li><li>插件 Node 脚本 glob；</li><li>PDF Viewer 独立预算；</li><li><code>file-type</code> 等第三方警告；</li><li>首屏 gzip、单 chunk 和总 JavaScript 体积预算检查。</li></ul><h2 id="_4-停止条件" tabindex="-1">4. 停止条件 <a class="header-anchor" href="#_4-停止条件" aria-label="Permalink to &quot;4. 停止条件&quot;">​</a></h2><ul><li>若自动分包和首批低风险懒加载没有稳定可测收益，保持当前 registry 模型并结束性能重构。</li><li>任一入口改造若改变同步公开契约、启动恢复或插件 discovery，应回退并另立架构计划。</li><li>完成 P1 和必要的 P4 预算后，将长期构建规则写入构建指南，删除本文。</li></ul><h2 id="_5-参考" tabindex="-1">5. 参考 <a class="header-anchor" href="#_5-参考" aria-label="Permalink to &quot;5. 参考&quot;">​</a></h2><ul><li><a href="https://vite.dev/config/build-options.html" target="_blank" rel="noreferrer">Vite Build Options</a></li><li><a href="https://vite.dev/blog/announcing-vite8" target="_blank" rel="noreferrer">Vite 8 发布说明</a></li><li><a href="https://rolldown.rs/in-depth/code-splitting" target="_blank" rel="noreferrer">Rolldown Code Splitting</a></li></ul>',36)])])}const g=t(l,[["render",r]]);export{u as __pageData,g as default};
